package com.fream.back.domain.m85.controller.command;


@RestController
@RequestMapping("/sales")
@RequiredArgsConstructor
public class Xpj42CommandController {

    private final Xpj42CommandService saleCommandService;



    @PostMapping("/{saleId}/shipment")
    public ResponseEntity<Void> createSellerShipment(
            @PathVariable("saleId") Long saleId,
            @RequestBody Xzn53RequestDto requestDto
    ) {
        saleCommandService.createSellerShipment(
                saleId,
                requestDto.getCourier(),
                requestDto.getTrackingNumber()
        );
        return ResponseEntity.ok().build();
    }
}
package com.fream.back.domain.m85.service.command;


@Service
@RequiredArgsConstructor
public class Xpj42CommandService {

    private final Xpj42Repository saleRepository;
    private final Xtw92QueryService orderBidQueryService;
    private final Xbp24CommandService notificationCommandService;
    private final Xjm45QueryService userQueryService;
    private final Xrg51CommandService sellerShipmentCommandService;
    private final Xfs39QueryService bankAccountQueryService;
    private final Xzj40CommandService saleBankAccountCommandService;


    @Transactional
    public Xpj42 createInstantSale(
            Long orderBidId,
            String sellerEmail,
            String returnAddress,
            String postalCode,
            String receiverPhone
    ) {

        Xtw92 orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        Xjm45 seller = userQueryService.findByEmail(sellerEmail);


        Xcc44 productSize = orderBid.getProductSize();


        Xpj42 sale = Xpj42.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .status(Xpj42Status.PENDING_SHIPMENT)
                .build();

        Xpj42 savedSale = saleRepository.save(sale);



        Xfs39InfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());
        Xzj40 saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );
        savedSale.assignSaleBankAccount(saleBankAccount);


        orderBid.assignSale(savedSale);
        orderBid.updateStatus(Xkh73Status.MATCHED);


        Xjm45 buyer = orderBid.getUser();
        notificationCommandService.createNotification(
                buyer.getId(),
                Xrv73.SHOPPING,
                Xbp24Type.BID,
                "구매 입찰에 판매자가 등록되었습니다. 확인해보세요!"
        );

        return savedSale;
    }

    @Transactional
    public Xpj42 createSale(Xjm45 seller, Xcc44 productSize, String returnAddress,
                           String postalCode, String receiverPhone, boolean isWarehouseStorage) {

        Xfs39InfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());


        Xpj42 sale = Xpj42.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .isWarehouseStorage(isWarehouseStorage)
                .status(Xpj42Status.PENDING_SHIPMENT)
                .build();

        Xpj42 savedSale = saleRepository.save(sale);


        Xzj40 saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );


        savedSale.assignSaleBankAccount(saleBankAccount);


        notificationCommandService.createNotification(
                seller.getId(),
                Xrv73.SHOPPING,
                Xbp24Type.BID,
                "판매 입찰이 등록되었습니다."
        );

        return savedSale;
    }


    @Transactional
    public Xrg51 createSellerShipment(Long saleId, String courier, String trackingNumber) {

        Xrg51 shipment = sellerShipmentCommandService.createSellerShipment(saleId, courier, trackingNumber);


        updateSaleStatus(saleId, Xpj42Status.IN_TRANSIT);

        return shipment;
    }

    @Transactional
    public void updateSaleStatus(Long saleId, Xpj42Status newStatus) {
        Xpj42 sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        System.out.println("현재 상태: " + sale.getStatus());
        System.out.println("전환하려는 상태: " + newStatus);
        if (!sale.getStatus().canTransitionTo(newStatus)) {
            throw new IllegalStateException("Xpj42 상태를 " + newStatus + "로 전환할 수 없습니다.");
        }

        sale.updateStatus(newStatus);
    }

    @Transactional
    public void deleteSale(Long saleId) {

        Xpj42 sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        saleRepository.delete(sale);
    }


}


package com.fream.back.domain.m85.entity;


@Entity @jakarta.persistence.Table(name = "sale")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xpj42  extends Xzh80Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "seller_id")
    private Xjm45 seller;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private Xcc44 productSize;

    private String returnAddress;
    private String postalCode;
    private String receiverPhone;

    @OneToOne(mappedBy = "sale", cascade = CascadeType.ALL, orphanRemoval = true)
    private Xjt45 payment;

    @OneToOne(mappedBy = "sale", cascade = CascadeType.ALL, orphanRemoval = true)
    private Xzj40 saleBankAccount;

    private boolean isWarehouseStorage;

    @Enumerated(EnumType.STRING)
    private Xpj42Status status;

    @OneToOne(mappedBy = "sale", cascade = CascadeType.ALL, orphanRemoval = true)
    private Xzt63 saleBid;

    @OneToOne(mappedBy = "sale", cascade = CascadeType.ALL, orphanRemoval = true)
    private Xrg51 sellerShipment;

    public void assignSaleBankAccount(Xzj40 saleBankAccount) {
        this.saleBankAccount = saleBankAccount;
        saleBankAccount.assignSale(this);
    }

    public void assignSaleBid(Xzt63 saleBid) {
        this.saleBid = saleBid;
        saleBid.assignSale(this);
    }

    public void assignPayment(Xjt45 payment) {
        this.payment = payment;
        payment.assignSale(this);
    }
    public void assignSellerShipment(Xrg51 sellerShipment) {
        this.sellerShipment = sellerShipment;
        sellerShipment.assignSale(this);
    }

    public void updateStatus(Xpj42Status newStatus) {
        this.status = newStatus;
    }
}
package com.fream.back.domain.m85.entity;

public enum Xpj42Status {
    PENDING_SHIPMENT,
    IN_TRANSIT,
    IN_INSPECTION,
    FAILED_INSPECTION,
    IN_STORAGE,
    ON_AUCTION,
    SELLING,
    SOLD,
    AUCTION_EXPIRED;


    public boolean canTransitionTo(Xpj42Status newStatus) {
        return switch (this) {
            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
            case IN_TRANSIT -> newStatus == IN_INSPECTION;
            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false;
        };
    }
}

