package com.fream.back.domain.m84.config;

import com.fream.back.domain.m84.aop.aspect.Xhp98ExceptionAspect;
import com.fream.back.domain.m84.aop.aspect.Xmr19Aspect;
import com.fream.back.domain.m84.aop.aspect.Xfg34Aspect;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cache.CacheManager;
import org.springframework.cache.concurrent.ConcurrentMapCacheManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.EnableAspectJAutoProxy;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;















@Configuration
