import com.fream.back.domain.m03.service.command.Xtc38CommandService;
import com.fream.back.domain.m45.entity.Xfr60;
import com.fream.back.domain.m45.entity.Xzn53Status;
import com.fream.back.domain.m45.exception.Xzn53ErrorCode;
import com.fream.back.domain.m45.exception.Xzn53Exception;
import com.fream.back.domain.m45.service.command.Xfr60CommandService;
import com.fream.back.global.utils.Xkh22;
import com.microsoft.playwright.Page;
import lombok.extern.slf4j.Slf4j;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.springframework.batch.item.ItemProcessor;





@Slf4j
public class Xcj35Processor implements ItemProcessor<Xfr60, Xfr60> {

    private final Xkh22 browserManager;
    private final Xtc38CommandService notificationService;
    private final Xfr60CommandService orderService;

    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
    private static final int TIMEOUT_MS = 30000;








    public Xcj35Processor(
            Xkh22 browserManager,
            Xtc38CommandService notificationService,
            Xfr60CommandService orderService
    ) {
        this.browserManager = browserManager;
        this.notificationService = notificationService;
        this.orderService = orderService;
    }








    @Override
    public Xfr60 process(Xfr60 orderShipment) throws Exception {
        String trackingNumber = orderShipment.getTrackingNumber();
        Long shipmentId = orderShipment.getId();

        if (trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
            throw new Xzn53Exception(Xzn53ErrorCode.TRACKING_NUMBER_INVALID);
        }

        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
                shipmentId, trackingNumber, orderShipment.getStatus());

        Page page = null;
        try {

            page = browserManager.newPage();
            if (page == null) {
                throw new Xzn53Exception(Xzn53ErrorCode.BROWSER_INITIALIZATION_ERROR);
            }


            page.setDefaultTimeout(TIMEOUT_MS);


            String url = TRACKING_URL_PREFIX + trackingNumber;
            log.debug("배송 조회 페이지로 이동: {}", url);
            page.navigate(url);


            log.debug("배송 상태 테이블 로드 대기");
            page.waitForSelector(STATUS_SELECTOR);


            String renderedHtml = page.content();
            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());


            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
            Xzn53Status newStatus = mapToShipmentStatus(statusText);

            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
                    shipmentId, statusText, newStatus);


            if (orderShipment.getStatus() == newStatus) {
                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                        shipmentId, newStatus);
                return orderShipment;
            }


            if (newStatus == Xzn53Status.DELIVERED) {
                log.info("배송 완료 처리: shipmentId={}, orderId={}",
                        shipmentId, orderShipment.getOrder().getId());


                orderShipment.updateStatus(Xzn53Status.DELIVERED);


                orderService.completeOrder(orderShipment.getOrder().getId());
                notificationService.notifyShipmentCompleted(orderShipment.getOrder());

            } else if (newStatus == Xzn53Status.OUT_FOR_DELIVERY) {
                log.info("배송 출발 처리: shipmentId={}", shipmentId);
                orderShipment.updateStatus(Xzn53Status.OUT_FOR_DELIVERY);

            } else {
                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                orderShipment.updateStatus(Xzn53Status.IN_TRANSIT);
            }

            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
                    shipmentId, orderShipment.getStatus());

            return orderShipment;

        } catch (Exception e) {
            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
                    shipmentId, trackingNumber, e.getMessage(), e);


            if (!(e instanceof Xzn53Exception)) {
                throw new Xzn53Exception(
                        Xzn53ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
                        e
                );
            }
            throw e;
        } finally {

            if (page != null) {
                try {
                    page.close();
                    log.debug("페이지 리소스 해제 완료");
                } catch (Exception e) {
                    log.warn("페이지 닫기 실패: {}", e.getMessage());
                }
            }
        }
    }









    private String parseStatusFromHtml(String html, String trackingNumber) {
        try {
            Document doc = Jsoup.parse(html);
            Elements rows = doc.select(STATUS_SELECTOR);

            if (rows.isEmpty()) {
                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
                throw new Xzn53Exception(
                        Xzn53ErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
                );
            }


            String statusText = rows.last().select("td").get(4).text().trim();

            if (statusText.isEmpty()) {
                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
                throw new Xzn53Exception(
                        Xzn53ErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 상태 정보를 찾을 수 없습니다."
                );
            }

            return statusText;

        } catch (IndexOutOfBoundsException e) {
            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
            throw new Xzn53Exception(
                    Xzn53ErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
                    e
            );
        } catch (Exception e) {
            if (e instanceof Xzn53Exception) {
                throw (Xzn53Exception) e;
            }

            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
            throw new Xzn53Exception(
                    Xzn53ErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
                    e
            );
        }
    }







    private Xzn53Status mapToShipmentStatus(String statusText) {
        return switch (statusText) {
            case "배송완료" -> Xzn53Status.DELIVERED;
            case "배송출발" -> Xzn53Status.OUT_FOR_DELIVERY;
            default -> Xzn53Status.IN_TRANSIT;
        };
    }
}package com.fream.back.domain.m81.controller.command;

import com.fream.back.domain.m45.dto.Xfr60RequestDto;
import com.fream.back.domain.m45.dto.Xzn53StatusResponse;
import com.fream.back.domain.m45.entity.Xzn53Status;
import com.fream.back.domain.m45.exception.Xzn53ErrorCode;
import com.fream.back.domain.m45.exception.Xzn53Exception;
import com.fream.back.domain.m45.service.command.Xfr60CommandService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;




@Slf4j
@RestController
@RequestMapping("/settlement/shipments/order")
@RequiredArgsConstructor
public class Xsd74CommandController {

    private final Xfr60CommandService orderShipmentCommandService;








    @PatchMapping("/{shipmentId}/status")
    public ResponseEntity<Void> updateTrackingInfo(
            @PathVariable Long shipmentId,
            @Validated @RequestBody Xfr60RequestDto requestDto
    ) {
        log.info("배송 운송장 정보 업데이트 요청: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());

        orderShipmentCommandService.updateTrackingInfo(
                shipmentId,
                requestDto.getCourier(),
                requestDto.getTrackingNumber()
        );

        log.info("배송 운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
        return ResponseEntity.ok().build();
    }








    @PostMapping("/{shipmentId}/check-status")
    public ResponseEntity<Xzn53StatusResponse> updateAndCheckStatus(
            @PathVariable("shipmentId") Long shipmentId,
            @Validated @RequestBody Xfr60RequestDto requestDto
    ) {
        log.info("배송 상태 즉시 조회 요청: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());

        try {

            Xzn53Status updatedStatus = orderShipmentCommandService.updateAndCheckShipmentStatus(
                    shipmentId,
                    requestDto.getCourier(),
                    requestDto.getTrackingNumber()
            );


            Xzn53StatusResponse response = new Xzn53StatusResponse(updatedStatus);
            log.info("배송 상태 조회 완료: shipmentId={}, status={}", shipmentId, updatedStatus);

            return ResponseEntity.ok(response);

        } catch (Xzn53Exception e) {
            log.error("배송 상태 조회 실패 (Xzn53Exception): shipmentId={}, code={}, message={}",
                    shipmentId, e.getErrorCode().getCode(), e.getMessage());

            return ResponseEntity
                    .status(e.getErrorCode().getStatus())
                    .build();

        } catch (Exception e) {
            log.error("배송 상태 조회 실패 (일반 예외): shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);

            return ResponseEntity.badRequest().build();
        }
    }








    @PostMapping("/{shipmentId}/check-status-string")
    public ResponseEntity<String> updateAndCheckStatusAsString(
            @PathVariable("shipmentId") Long shipmentId,
            @Validated @RequestBody Xfr60RequestDto requestDto
    ) {
        log.info("배송 상태 즉시 조회 요청 (문자열 응답): shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());

        try {
            Xzn53Status updatedStatus = orderShipmentCommandService.updateAndCheckShipmentStatus(
                    shipmentId,
                    requestDto.getCourier(),
                    requestDto.getTrackingNumber()
            );

            log.info("배송 상태 조회 완료 (문자열 응답): shipmentId={}, status={}",
                    shipmentId, updatedStatus);


            return ResponseEntity.ok(updatedStatus.name());

        } catch (Xzn53Exception e) {
            log.error("배송 상태 문자열 조회 실패 (Xzn53Exception): shipmentId={}, code={}, message={}",
                    shipmentId, e.getErrorCode().getCode(), e.getMessage());

            return ResponseEntity
                    .status(e.getErrorCode().getStatus())
                    .body("Error: " + e.getMessage());

        } catch (Exception e) {
            log.error("배송 상태 문자열 조회 실패 (일반 예외): shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);

            return ResponseEntity.badRequest().body("Error: " + e.getMessage());
        }
    }
}

