    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Xnd96> orderItems = new ArrayList<>();

    @OneToOne(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
    private Xtw92 orderBid;






    public void addOrderItem(Xnd96 orderItem) {
        orderItems.add(orderItem);
        orderItem.addOrder(this);
    }






    public void assignPayment(Xjt45 payment) {
        this.payment = payment;
        if (payment != null && payment.getOrder() != this) {
            payment.assignOrder(this);
        }
    }






    public void assignOrderShipment(Xfr60 orderShipment) {
        this.orderShipment = orderShipment;
        if (orderShipment != null && orderShipment.getOrder() != this) {
            orderShipment.assignOrder(this);
        }
    }






    public void assignWarehouseStorage(Xms75 warehouseStorage) {
        this.warehouseStorage = warehouseStorage;
        if (warehouseStorage != null && warehouseStorage.getOrder() != this) {
            warehouseStorage.assignOrder(this);
        }
    }








    public void updateStatus(Xhq12Status newStatus) {
        if (this.status == null || this.status.canTransitionTo(newStatus)) {
            this.status = newStatus;
        } else {
            throw new Xxm16StatusException(
                    String.format("상태 전환이 허용되지 않습니다: %s -> %s", this.status, newStatus)
            );
        }
    }






    public void assignOrderBid(Xtw92 orderBid) {
        this.orderBid = orderBid;
        if (orderBid != null && orderBid.getOrder() != this) {
            orderBid.assignOrder(this);
        }
    }
}
package com.fream.back.domain.m99.entity;

import java.util.*;




public enum Xhq12Status {
    PENDING_PAYMENT,
    PAYMENT_COMPLETED,
    PREPARING,
    IN_WAREHOUSE,
    SHIPMENT_STARTED,
    IN_TRANSIT,
    COMPLETED,
    REFUND_REQUESTED,
    REFUNDED;


    private static final Map<Xhq12Status, Set<Xhq12Status>> ALLOWED_TRANSITIONS = new HashMap<>();

    static {

        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
    }







    public boolean canTransitionTo(Xhq12Status newStatus) {
        Set<Xhq12Status> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
        return allowedNextStates != null && allowedNextStates.contains(newStatus);
    }






    public Set<Xhq12Status> getAllowedNextStates() {
        return Collections.unmodifiableSet(ALLOWED_TRANSITIONS.getOrDefault(this, Collections.emptySet()));
    }
