private final Xfr60CommandService orderShipmentCommandService;
private final Xrj56CommandService orderItemCommandService;
private final Xnw92QueryService orderBidQueryService;
private final Xqr16QueryService userQueryService;
private final Xms75CommandService warehouseStorageCommandService;
private final Xjq23QueryService addressQueryService;
private final EntityManager entityManager;
@Transactional
public Xhq12 createOrderFromBid(Xjm45 user, Xcc44 productSize, int bidPrice) {
    try {
        if (user == null) {
            throw new Xwn18Exception("사용자 정보가 없습니다.");
        }
        if (productSize == null) {
            throw new Xpb58Exception("상품 사이즈 정보가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new Xrs16Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
        Xnd96 orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);
        Xhq12 order = Xhq12.builder()
                .user(user)
                .totalAmount(bidPrice)
                .discountAmount(0)
                .usedPoints(0)
                .status(Xhq12Status.PENDING_PAYMENT)
                .build();
        order.addOrderItem(orderItem);
        return orderRepository.save(order);
    } catch (Exception e) {
        if (e instanceof Xhq12Exception) {
            throw e;
        }
        log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
        throw new Xvq37Exception("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
    }
}
@Transactional
public void processPaymentAndShipment(Long orderId, String userEmail, Xsw86RequestDto requestDto) {
    if (orderId == null) {
        throw new Xwn18Exception("주문 ID가 없습니다.");
    }
    if (userEmail == null || userEmail.trim().isEmpty()) {
        throw new Xjf78Exception("사용자 정보가 없습니다.");
    }
    if (requestDto == null) {
        throw new Xtv55Exception("결제 및 배송 정보가 없습니다.");
    }
    try {
        Xjm45 user = userQueryService.findByEmail(userEmail);
        Xhq12 order = orderRepository.findById(orderId)
                .orElseThrow(() -> new Xhr44Exception("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
        if (!order.getUser().getId().equals(user.getId())) {
            throw new Xjf78Exception("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
        }
        validatePaymentShipmentRequest(requestDto);
        try {
            Xjt45 payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
            order.assignPayment(payment);
        } catch (Exception e) {
            log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
            throw new Xwf42Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
        try {
            Xfr60 shipment = orderShipmentCommandService.createOrderShipment(
                    order,
                    requestDto.getReceiverName(),
                    requestDto.getReceiverPhone(),
                    requestDto.getPostalCode(),
                    requestDto.getAddress()
            );
            order.assignOrderShipment(shipment);
        } catch (Exception e) {
            log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
            throw new Xjb41Exception("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
        try {
            if (requestDto.isWarehouseStorage()) {
                order.updateStatus(Xhq12Status.PAYMENT_COMPLETED);
                order.updateStatus(Xhq12Status.PREPARING);
                order.updateStatus(Xhq12Status.IN_WAREHOUSE);
                Xms75 warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
                order.assignWarehouseStorage(warehouseStorage);
                order.updateStatus(Xhq12Status.COMPLETED);
            } else {
                order.updateStatus(Xhq12Status.PAYMENT_COMPLETED);
                order.updateStatus(Xhq12Status.PREPARING);
            }
        } catch (Xms75Exception e) {
            log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
            throw new Xkd21Exception("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
        } catch (Exception e) {
            log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
            throw new Xbb45Exception("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
        try {
            orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
                orderBid.updateStatus(Xkh73Status.MATCHED);
            });
        } catch (Exception e) {
            log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
        }
    } catch (Exception e) {
        if (e instanceof Xhq12Exception) {
            throw e;
        }
        log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
        throw new Xwf42Exception("결제 및 배송 처리 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
    }
}
@Transactional
public Xhq12 createInstantOrder(Xjm45 buyer, Xzt63 saleBid, Long addressId,
                                boolean isWarehouseStorage, Xjt45RequestDto paymentRequest) {
    try {
        if (buyer == null) {
            throw new Xwn18Exception("구매자 정보가 없습니다.");
        }
        if (saleBid == null) {
            throw new Xbk76Exception("판매 입찰 정보가 없습니다.");
        }
        if (addressId == null) {
            throw new Xwn18Exception("배송지 정보가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new Xtv55Exception("결제 정보가 없습니다.");
        }
        Xms98ResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
        Xhq12 order = Xhq12.builder()
                .user(buyer)
                .totalAmount(saleBid.getBidPrice())
                .status(Xhq12Status.PENDING_PAYMENT)
                .build();
        order = orderRepository.save(order);
        paymentRequest.setOrderId(order.getId());
        log.debug("결제 요청 정보: {}", paymentRequest);
        try {
            Xnd96 orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
            order.addOrderItem(orderItem);
        } catch (Exception e) {
            log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new Xxx52Exception("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
        try {
            Xfr60 orderShipment = orderShipmentCommandService.createOrderShipment(
                    order,
                    address.getRecipientName(),
                    address.getPhoneNumber(),
                    address.getZipCode(),
                    address.getAddress()
            );
            order.assignOrderShipment(orderShipment);
        } catch (Exception e) {
            log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new Xjb41Exception("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
        try {
            saleBid.assignOrder(order);
            saleBid.updateStatus(com.fream.back.domain.m85.entity.Xkh73Status.MATCHED);
            entityManager.flush();
        } catch (Exception e) {
            log.error("판매 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
            throw new Xfb77Exception("판매 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
        try {
            Xpj42 sale = saleBid.getSale();
            if (sale != null && sale.isWarehouseStorage()) {
                warehouseStorageCommandService.updateWarehouseStatus(sale, Xbj62Status.ASSOCIATED_WITH_ORDER);
            }
        } catch (Xms75Exception e) {
            log.error("창고 보관 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
            throw new Xkd21Exception("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
        } catch (Exception e) {
            log.error("창고 보관 상태 업데이트 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
            throw new Xkd21Exception("창고 보관 상태 업데이트 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);

